window.docContents[33].resolve({"/Incomplete-Gamma-and-Related-Functions/#chapter-8":{"contents":"LMLF's accepted complete-Gamma wrapper is a dependency candidate, not Chapter 8 coverage. Lower,\nupper, normalized, incomplete-beta, and generalized integral objects remain unidentified.\n\nThe chapter requires separate base-domain integrals, continuation and exceptional-parameter policies,\nnormalization bridges, and then paired asymptotic and explicit-remainder results. None is accepted on\nmain yet.\n\n\n\n","context":"LMLF · Mathematical Functions with Lean","header":"8. Incomplete Gamma and Related Functions","id":"/Incomplete-Gamma-and-Related-Functions/#chapter-8"}});